#!/usr/bin/env python3
"""Reproduce Phase 3C metadata-only decisions before any OBJ extraction.

Reads the preserved six BP3D metadata tables and pinned ZIP central directory.
Reuses the unchanged pinned Phase 3B metadata archive; no network requests.
No OBJ is extracted, parsed, converted, or generated by this script.
"""
from __future__ import annotations
import argparse
import collections
import csv
import hashlib
import io
import json
import re
import struct
import urllib.request
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
BASE = 'https://dbarchive.biosciencedbc.jp/data/bodyparts3d/20130619/'
CACHE = ROOT / '.cache/bodyparts3d-4.0/metadata'
SOURCE = ROOT / 'research/anatomy/torso-metadata.zip'
OUTPUT = ROOT / 'research/anatomy/limbs-selection.json'
DOC = ROOT / 'docs/phase3c-audit.md'
TABLES = {
    'isa_parts_list_e.txt': 'ab7796deedd49205e77f3609a1cb8c53e2bbee14ecb5c9a6ca05227469780513',
    'isa_element_parts.txt': 'a3de74423f943b0d724ae8f59b3a817f87c423a544f8db98113b1980817cbeaf',
    'isa_inclusion_relation_list.txt': '26e7d818e03a8c909fe09c561f38d0d513423c87681f9450a803bc38f5b07564',
    'partof_parts_list_e.txt': '9224080557053e6f1322f1e13ab27f0ecde0db19bb3b505f0631afad230eeebd',
    'partof_element_parts.txt': '3f5f6df1028eb122b30de77c711597b6bb8e5541658e5985859fd228adbf88ea',
    'partof_inclusion_relation_list.txt': '1b40738270931e3c1d955ce34e0fce0d8d10d8c5ad543463e40b4b4c0243007c',
}
CD_NAME = 'isa_BP3D_4.0_obj_99.central-directory.bin'
CD_OFFSET, CD_BYTES, ARCHIVE_BYTES = 142733851, 170025, 142903898
CD_SHA = 'edde15c7c5f34b2b9743935fb3c1873cce3a9789164427ddf8343c879bcde96b'
ARCHIVE_URL = BASE + 'isa_BP3D_4.0_obj_99.zip'


# Explicit pairs reviewed against source names and single-element bindings.
PAIRS = [('gluteusmaximus', 'Glúteo mayor', 'gluteal', 'gluteal', None, 'FMA22328', 'FMA22329', 'FJ1418', 'FJ1418M'), ('gluteusmedius', 'Glúteo medio', 'gluteal', 'gluteal', None, 'FMA22330', 'FMA22331', 'FJ1419', 'FJ1419M'), ('gluteusminimus', 'Glúteo menor', 'gluteal', 'gluteal', None, 'FMA22332', 'FMA22333', 'FJ1420', 'FJ1420M'), ('tensorfasciaelatae', 'Tensor de la fascia lata', 'gluteal', 'gluteal', None, 'FMA22425', 'FMA22426', 'FJ1438', 'FJ1438M'), ('rectusfemoris', 'Recto femoral', 'thigh', 'anterior', None, 'FMA38928', 'FMA38929', 'FJ1433', 'FJ1433M'), ('vastuslateralis', 'Vasto lateral', 'thigh', 'anterior', None, 'FMA38930', 'FMA38931', 'FJ1442', 'FJ1442M'), ('vastusmedialis', 'Vasto medial', 'thigh', 'anterior', None, 'FMA38932', 'FMA38933', 'FJ1443', 'FJ1443M'), ('vastusintermedius', 'Vasto intermedio', 'thigh', 'anterior', None, 'FMA38934', 'FMA38935', 'FJ1441', 'FJ1441M'), ('sartorius', 'Sartorio', 'thigh', 'anterior', None, 'FMA22354', 'FMA22355', 'FJ1434', 'FJ1434M'), ('adductorlongus', 'Aductor largo', 'thigh', 'medial', None, 'FMA22456', 'FMA22457', 'FJ1402', 'FJ1402M'), ('gracilis', 'Grácil', 'thigh', 'medial', None, 'FMA43883', 'FMA43884', 'FJ1421', 'FJ1421M'), ('bicepsfemoris', 'Bíceps femoral', 'thigh', 'posterior', 'long', 'FMA45888', 'FMA45889', 'FJ1395', 'FJ1395M'), ('bicepsfemoris', 'Bíceps femoral', 'thigh', 'posterior', 'short', 'FMA45891', 'FMA45892', 'FJ1444', 'FJ1444M'), ('semitendinosus', 'Semitendinoso', 'thigh', 'posterior', None, 'FMA22358', 'FMA22359', 'FJ1436', 'FJ1436M'), ('semimembranosus', 'Semimembranoso', 'thigh', 'posterior', None, 'FMA22448', 'FMA22449', 'FJ1435', 'FJ1435M'), ('tibialisanterior', 'Tibial anterior', 'leg', 'anterior', None, 'FMA22544', 'FMA22545', 'FJ1439', 'FJ1439M'), ('fibularislongus', 'Fibular largo', 'leg', 'lateral', None, 'FMA22552', 'FMA22553', 'FJ1410', 'FJ1410M'), ('fibularisbrevis', 'Fibular corto', 'leg', 'lateral', None, 'FMA22554', 'FMA22555', 'FJ1409', 'FJ1409M'), ('gastrocnemius', 'Gastrocnemio', 'leg', 'posterior', 'medial', 'FMA45957', 'FMA45958', 'FJ1397', 'FJ1397M'), ('gastrocnemius', 'Gastrocnemio', 'leg', 'posterior', 'lateral', 'FMA45960', 'FMA45961', 'FJ1394', 'FJ1394M'), ('soleus', 'Sóleo', 'leg', 'posterior', None, 'FMA22558', 'FMA22559', 'FJ1437', 'FJ1437M'), ('tibialisposterior', 'Tibial posterior', 'leg', 'posterior', None, 'FMA65018', 'FMA65019', 'FJ1440', 'FJ1440M'), ('flexorcarpiradialis', 'Flexor radial del carpo', 'forearm', 'anterior', None, 'FMA38460', 'FMA38461', 'FJ1496', 'FJ1496M'), ('pronatorteres', 'Pronador redondo', 'forearm', 'anterior', 'humeral', 'FMA38560', 'FMA38561', 'FJ1474', 'FJ1474M'), ('pronatorteres', 'Pronador redondo', 'forearm', 'anterior', 'ulnar', 'FMA38562', 'FMA38563', 'FJ1516', 'FJ1516M'), ('extensorcarpiradialislongus', 'Extensor radial largo del carpo', 'forearm', 'posterior', None, 'FMA38495', 'FMA38496', 'FJ1490', 'FJ1490M'), ('supinator', 'Supinador', 'forearm', 'posterior', None, 'FMA38513', 'FMA38514', 'FJ1505', 'FJ1505M')]

def sha(data):
    return hashlib.sha256(data).hexdigest()


def write_json(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8', newline='\n')


with zipfile.ZipFile(SOURCE) as archive:
    assert set(archive.namelist()) == set(TABLES) | {CD_NAME}
    raw = {name: archive.read(name) for name in archive.namelist()}
for name, expected in {**TABLES, CD_NAME: CD_SHA}.items():
    assert sha(raw[name]) == expected, 'Pinned source mismatch: ' + name

tables = {name: list(csv.DictReader(io.StringIO(raw[name].decode()), delimiter='\t')) for name in TABLES}
parts = {r['concept id']: r for r in tables['isa_parts_list_e.txt']}
edges = tables['isa_inclusion_relation_list.txt']
parents = {r['child id']: r for r in edges}
nonterminal = {r['parent id'] for r in edges}
bindings = collections.defaultdict(list)
for row in tables['isa_element_parts.txt']:
    bindings[row['concept id']].append(row['element file id'])
directory, offset = {}, 0
while offset < len(raw[CD_NAME]):
    header = struct.unpack_from('<4s6H3L5H2L', raw[CD_NAME], offset)
    assert header[0] == b'PK\x01\x02'
    path = raw[CD_NAME][offset + 46:offset + 46 + header[10]].decode()
    directory[Path(path).stem] = dict(path=path, bytes=header[9], compressedBytes=header[8],
        crc32=f'{header[7]:08x}', offset=header[16], method=header[4])
    offset += 46 + header[10] + header[11] + header[12]
assert len(directory) == 2234


def ancestry(cid):
    result = []
    while cid in parents:
        edge = parents[cid]
        result.append({'id': edge['parent id'], 'name': edge['parent name']})
        cid = edge['parent id']
    return result


def isa_type(cid):
    ids = {r['id'] for r in ancestry(cid)} | {cid}
    for key, value in [('FMA85453', 'head of muscle organ'), ('FMA10474', 'zone of muscle organ'),
                       ('FMA5022', 'muscle organ'), ('FMA55268', 'organ zone')]:
        if key in ids:
            return value
    return 'set/group or other anatomical entity'


def side_from_name(name):
    if 'right' in name:
        return 'right'
    if 'left' in name:
        return 'left'
    return 'unspecified'


QUADRICEPS = {'rectusfemoris', 'vastuslateralis', 'vastusmedialis', 'vastusintermedius'}
REGIONS = {'gluteal': 'Región glútea', 'thigh': 'Muslo', 'leg': 'Pierna', 'forearm': 'Antebrazo'}
COMPONENTS = {'long': 'cabeza larga', 'short': 'cabeza corta', 'medial': 'cabeza medial',
              'lateral': 'cabeza lateral', 'humeral': 'cabeza humeral', 'ulnar': 'cabeza ulnar'}
approved = []
for family, label, region, compartment, component, right, left, right_fj, left_fj in PAIRS:
    for side, cid, fid in [('right', right, right_fj), ('left', left, left_fj)]:
        row = parts[cid]
        assert bindings[cid] == [fid] and side_from_name(row['en']) == side and fid in directory
        rid = f'muscular:region:arm-{side}:forearm' if region == 'forearm' else f'muscular:region:leg-{side}:{region}'
        parent = rid if region == 'gluteal' else f'{rid}:{compartment}'
        if family in QUADRICEPS:
            parent = f'muscular:group:quadriceps:{side}'
        structure = f'med3d:muscle:{family}:{side}' if component else 'bp3d:' + cid
        typ = isa_type(cid)
        reason = ('Identidad bilateral y FJ únicos; cabeza conservada como componente del músculo documentado.' if component else
                  'BP3D lo clasifica como zona; se representa como uno de los cuatro músculos del grupo cuádriceps, documentados por OpenStax y UW. El grupo no se cuenta como otro músculo.' if family in QUADRICEPS else
                  'Muscle organ con nombre lateralizado y un único FJ; conjunto regional acotado.')
        approved.append(dict(elementId=fid, sourceId=cid, representationId=row['representation id'],
            en=row['en'], name=label + (', ' + COMPONENTS[component] if component else ''),
            side=side, family=family, component=component, region=region, compartment=compartment,
            sourceType='head' if typ == 'head of muscle organ' else 'portion' if typ == 'zone of muscle organ' else 'muscle',
            isaType=typ, isaAncestry=ancestry(cid), structureId=structure,
            muscleParent=label if component else 'Grupo cuádriceps (no músculo adicional)' if family in QUADRICEPS else 'No aplica: músculo',
            proposedParentId=structure if component else parent, regionId=rid,
            moduleId=f'muscular:{region}-{side}', moduleFile=f'muscular-{region}-{side}.glb',
            archiveEntry=directory[fid], decision='APROBADO', reason=reason, originalHeaderNotYetInspected=True))
assert len(approved) == 54 and len({r['structureId'] for r in approved}) == 48
assert len({r['family'] for r in approved}) == 24
approved_ids = {r['sourceId'] for r in approved}
approved_fj = {r['elementId'] for r in approved}
old_fj = set()
for name in ['muscular-pilot-source-lock.json', 'muscular-torso-source-lock.json']:
    old_fj.update(r['elementId'] for r in json.loads((ROOT / 'research/anatomy' / name).read_text())['files'])
assert not old_fj & approved_fj

# Declared name-based candidate universe, including non-muscular homonyms so
# that discarded vessels, membranes and retinacula are visible in the audit.
pattern = re.compile(r'glute|tensor fascia|piriform|obturator|gemellus|quadratus femor|femoris|vastus|sartorius|adductor|gracilis|pectineus|semitendin|semimembran|tibialis|fibularis|peroneus|gastrocnem|soleus|plantaris|popliteus|flexor|extensor|pronator|supinator|abductor|opponens|lumbrical|interosse|iliacus|psoas|brachioradialis|palmaris')
other = []
for cid, row in parts.items():
    if cid in approved_ids or cid in nonterminal or not bindings[cid] or not pattern.search(row['en']):
        continue
    typ, name, fids = isa_type(cid), row['en'], bindings[cid]
    muscular = typ in ['muscle organ', 'head of muscle organ', 'zone of muscle organ'] or name.startswith('set of')
    decision = 'PENDIENTE' if muscular else 'DESCARTADO'
    reason = 'Identificable, aplazado para limitar esta entrega a 24 familias y ocho módulos; no se afirma ausencia en la fuente.'
    if not muscular:
        reason = 'Coincidencia nominal vascular, membrana u otra estructura no muscular; no se integra como músculo.'
    elif len(fids) != 1:
        reason = 'Varios FJ para un concepto sin desglose terminal suficiente; no se convierten en músculos independientes.'
    elif 'set of' in name:
        reason = 'Conjunto agregado: requiere desglose anatómico verificable antes de integrar músculos intrínsecos.'
    elif 'flexor pollicis brevis' in name:
        reason = 'Relación entre elemento del músculo y cabeza representada pendiente; no se duplican representaciones ni se infiere lado del sufijo FJ.'
    if set(fids) & old_fj:
        decision, reason = 'DESCARTADO', 'Elemento ya integrado en Fase 3A/3B; se conserva su nodo y no se duplica.'
    if any(t in name for t in ['glute', 'piriform', 'obturator', 'gemellus', 'quadratus femor', 'tensor fascia']): region = 'gluteal'
    elif any(t in name for t in ['femoris', 'vastus', 'sartorius', 'gracilis', 'pectineus', 'semitendin', 'semimembran', 'adductor longus', 'adductor brevis', 'adductor magnus', 'adductor minimus']): region = 'thigh'
    elif any(t in name for t in ['tibialis', 'peroneus', 'fibularis', 'gastrocnem', 'soleus', 'plantaris', 'popliteus', 'hallucis longus', 'digitorum longus']): region = 'leg'
    elif any(t in name for t in ['of foot', 'hallucis', 'plantar', 'digitorum brevis']): region = 'foot'
    elif any(t in name for t in ['of hand', 'pollicis brevis', 'adductor pollicis', 'opponens', 'lumbrical', 'interossei']): region = 'hand'
    elif any(t in name for t in ['carpi', 'digitorum superficialis', 'digitorum profundus', 'pollicis longus', 'pronator', 'supinator', 'brachioradialis', 'palmaris', 'extensor indicis', 'extensor digitorum', 'extensor digiti minimi']): region = 'forearm'
    else: region = 'Por confirmar'
    other.append(dict(sourceId=cid, representationId=row['representation id'], en=name, name=name,
        elementIds=fids, side=side_from_name(name), isaType=typ, isaAncestry=ancestry(cid),
        muscleParent='Por curar' if typ != 'muscle organ' else 'No aplica: músculo',
        region=region, compartment='No asignado; fuera del conjunto aprobado', moduleId='No asignado',
        decision=decision, reason=reason, archiveEntries={fid: directory[fid] for fid in fids}))
other.sort(key=lambda r: (r['en'], r['sourceId']))
assert not approved_fj & {f for r in other for f in r['elementIds']}
modules = []
for aid in dict.fromkeys(r['moduleId'] for r in approved):
    members = [r for r in approved if r['moduleId'] == aid]
    modules.append(dict(id=aid, filename=members[0]['moduleFile'], regionId=members[0]['regionId'],
        meshes=len(members), structures=len({r['structureId'] for r in members}),
        upstreamObjBytes=sum(r['archiveEntry']['bytes'] for r in members),
        upstreamCompressedBytes=sum(r['archiveEntry']['compressedBytes'] for r in members)))
counts = dict(families=24, structures=48, meshes=54, modules=len(modules),
    candidates=len(approved) + len(other), approvedConceptRows=len(approved),
    discardedConceptRows=sum(r['decision']=='DESCARTADO' for r in other),
    pendingConceptRows=sum(r['decision']=='PENDIENTE' for r in other))
notes = [
    'Universo declarado: conceptos terminales con FJ cuyo nombre coincide con el patrón publicado. No es todo BP3D ni todos los músculos humanos; ancestros agregados no se suman otra vez.',
    'Cuádriceps: BP3D clasifica recto femoral y tres vastos como zone of muscle organ. Se conserva esa clase en la procedencia; OpenStax 11.6 y las cuatro fichas UW justifican cuatro músculos bajo un grupo editorial, sin inventar una arista PART-OF ni un quinto músculo.',
    'Bíceps femoral, gastrocnemio y pronador redondo: cada pareja de cabezas forma un músculo por lado; padres editoriales documentados, no aristas IS-A convertidas a PART-OF.',
    'No se encontraron nombres de cuádriceps, gastrocnemio o bíceps femoral en la tabla nominal PART-OF 4.0 inspeccionada; no se atribuye a esa tabla la jerarquía editorial.',
    'Mano y pie intrínsecos quedan aplazados por alcance y curación de sus conjuntos/componentes. No se crean regiones vacías ni se afirma que todos los elementos sean ambiguos.',
    'Ningún OBJ ni encabezado ha sido extraído durante esta auditoría. Vértices, caras, bounds y coincidencia espacial se verificarán después únicamente para los aprobados.',
]
grouping_sources = ['https://openstax.org/books/anatomy-and-physiology-2e/pages/11-6-appendicular-muscles-of-the-pelvic-girdle-and-lower-limbs'] + ['https://rad.uw.edu/muscle-atlas/' + slug for slug in ['rectus-femoris','vastus-lateralis','vastus-medialis','vastus-intermedius','biceps-femoris-long-head','biceps-femoris-short-head','gastrocnemius','pronator-teres']]
audit = dict(phase='3C', decision='approved-local-pre-extraction', checkedDate='2026-09-23',
    baselineCommit='1d58140bec7cdf946f3400d461a218756799bbc5',
    source=dict(name='BodyParts3D 4.0 OBJ99 / DBCLS', url=ARCHIVE_URL, archiveBytes=ARCHIVE_BYTES,
        centralDirectoryOffset=CD_OFFSET, centralDirectoryBytes=CD_BYTES, centralDirectorySha256=CD_SHA,
        archiveEntries=2234, fullArchiveDownloaded=False, geometryExtractedDuringAudit=False,
        metadataArchive='research/anatomy/torso-metadata.zip', metadataArchiveSha256=sha(SOURCE.read_bytes())),
    metadataChecks=[dict(filename=n, url=BASE+n, bytes=len(raw[n]), sha256=sha(raw[n])) for n in TABLES],
    counts=counts, modules=modules, approved=approved, other=other,
    discovery=dict(candidatePattern=pattern.pattern), groupingNotes=notes, groupingSources=grouping_sources)
write_json(OUTPUT, audit)
lines = ['# Fase 3C — auditoría previa de extremidades', '',
    'Base exacta: `1d58140bec7cdf946f3400d461a218756799bbc5`. Revisión de metadatos: 23 de septiembre de 2026.', '',
    '**Decisión previa a extraer: 24 familias bilaterales, 48 músculos, 54 FJ y ocho módulos.**', '',
    'Se reutilizan sin modificación las seis tablas y el directorio ZIP fijados en [los metadatos de Fase 3B](../research/anatomy/torso-metadata.zip). La [selección estructurada](../research/anatomy/limbs-selection.json) conserva hashes, ascendencia IS-A, identidades, decisión y cada entrada del directorio.', '',
    'Reproducir sin red ni OBJ: `python scripts/anatomy/audit-limbs-inventory.py`.', '',
    f"Candidatos terminales: {counts['candidates']}; APROBADO: 54; DESCARTADO: {counts['discardedConceptRows']}; PENDIENTE: {counts['pendingConceptRows']}.", '',
    *[note + '\n' for note in notes], '## Tabla de decisiones', '',
    '| Nombre | FMA | FJ | Lado | Tipo BP3D | Músculo padre | Región | Compartimento | Módulo previsto | Decisión | Motivo |',
    '|---|---|---|---|---|---|---|---|---|---|---|']
for r in approved + other:
    fids = r.get('elementIds', [r.get('elementId')])
    lines.append('| ' + ' | '.join(str(v).replace('|','/') for v in [r['name'], r['sourceId'], ', '.join(fids), r['side'], r['isaType'], r['muscleParent'], r['region'], r['compartment'], r['moduleId'], r['decision'], r['reason']]) + ' |')
lines += ['', '## Módulos aprobados', '', '| Módulo | Músculos | Mallas | OBJ bytes originales |', '|---|---:|---:|---:|']
for m in modules: lines.append(f"| {m['id']} | {m['structures']} | {m['meshes']} | {m['upstreamObjBytes']} |")
lines += ['', '## Fuentes de agrupación', '', *['- ['+url.rsplit('/',1)[-1]+']('+url+')' for url in grouping_sources], '']
DOC.write_text('\n'.join(lines), encoding='utf-8', newline='\n')
print(json.dumps(dict(**counts, selectionSha256=sha(OUTPUT.read_bytes())), indent=2))
